// Wraps the OpenNext worker:
// - @polyradar/db reads DATABASE_URL, which here comes from the Hyperdrive binding.
// - Pages are cached at the edge. Data only changes when a collection run lands
//   (every ~15 minutes), and on the Workers free plan a render can exceed the
//   10 ms CPU budget, so most requests are answered from cache. A stale copy is
//   served at once and refreshed in the background.
// @ts-ignore generated by `opennextjs-cloudflare build`
import handler from './.open-next/worker.js';

interface Env { HYPERDRIVE: { connectionString: string } }
interface Ctx { waitUntil(p: Promise<unknown>): void }

const FRESH_SEC = 600;
const KEEP_SEC = 86400;
const STAMP = 'x-polyradar-cached-at';

const cacheable = (req: Request) => {
  if (req.method !== 'GET' || req.headers.has('authorization')) return false;
  const { pathname } = new URL(req.url);
  return !pathname.startsWith('/mcp') && !pathname.startsWith('/_next/');
};

async function render(req: Request, env: Env, ctx: Ctx, cache: Cache): Promise<Response> {
  const res: Response = await handler.fetch(req, env, ctx);
  if (res.status === 200) {
    const copy = new Response(res.clone().body, res);
    copy.headers.set('cache-control', `public, max-age=${KEEP_SEC}`);
    copy.headers.set(STAMP, String(Date.now()));
    copy.headers.delete('set-cookie');
    ctx.waitUntil(cache.put(req.url, copy));
  }
  return res;
}

export default {
  async fetch(req: Request, env: Env, ctx: Ctx) {
    process.env.DATABASE_URL = env.HYPERDRIVE.connectionString;
    if (!cacheable(req)) return handler.fetch(req, env, ctx);

    const cache = (caches as unknown as { default: Cache }).default;
    const hit = await cache.match(req.url);
    if (!hit) return render(req, env, ctx, cache);

    const age = (Date.now() - Number(hit.headers.get(STAMP) ?? 0)) / 1000;
    if (age > FRESH_SEC) ctx.waitUntil(render(new Request(req.url, { headers: req.headers }), env, ctx, cache).catch(() => {}));
    const out = new Response(hit.body, hit);
    out.headers.set('cache-control', 'public, max-age=0, must-revalidate');
    out.headers.delete(STAMP);
    return out;
  },
};
